  // Opcion elegida dentro de una cinematica (linea "elige"): efectos, banderas y cartas futuras (luego), sin pasar de semana.
  S.aplicarOpcionCine = function (op, id) {
    if (!op) return;
    S.ctxPj = ""; S.modOn = true;
    S.aplicarE(S.conRuido(op));
    S.aplicarExtras(op, "");
    S.modOn = false;
