  // ---- fin de gestion ----
  // tipo: "stat" (dato = indice), "raro" (dato = id), "derrota" (dato = id del ganador),
  //       "retiro", "limite".
  S.terminar = function (tipo, dato) {
    S.setEstado("fin");
    S.senal.fin++;
    U.ev("caida");
    let texto, causaKey, titulo, forzado = null;
    if (tipo === "raro") {
