      texto = S.data.finales[causaKey] || ""; titulo = "FIN DE LA GESTIÓN";
    } else if (tipo === "uan") {
      causaKey = dato;
      texto = (S.data.caidas[dato] || {}).texto || "Uno de los pilares de la Universidad llegó a su límite durante tu gestión.";
