    } else if (cfg.tipo === "plagio" && ((D.originales || []).length && (D.plagiados || []).length)) {
      m.frag = []; m.next = 0.3; m.hits = 0; m.falsos = 0; m.perdidos = 0; m.t = 20;
      setTxt(S.o.pj, "COMITÉ DE INTEGRIDAD");
